    // 412 when the object exists. 409 when another write to the same key is still in progress, which is the same
    // collision a moment earlier.
    private static boolean isCollision(S3Exception e) {
        return e.statusCode() == 412 || e.awsErrorDetails() != null
                && "ConditionalRequestConflict".equals(e.awsErrorDetails().errorCode());
    }

    // A value S3 would refuse is left out, so a strange User-Agent can't fail the upload. The processor reads a missing
    // field as unknown.
    private static Map<String, String> metadata(LogObject object) {
        Map<String, String> metadata = new HashMap<>();
        putIfStorable(metadata, ObjectMetadataKeys.USER_AGENT, object.userAgent());
        putIfStorable(metadata, ObjectMetadataKeys.SOURCE_IP, Optional.of(object.sourceIp()));
        putIfStorable(metadata, ObjectMetadataKeys.CERT_SERIAL, Optional.of(object.certSerial()));
        metadata.put(ObjectMetadataKeys.MANUAL, Boolean.toString(object.manual()));
        putIfStorable(metadata, ObjectMetadataKeys.ORIGINAL_NAME, Optional.of(object.originalName()));
        return metadata;
    }

    private static void putIfStorable(Map<String, String> metadata, String name, Optional<String> value) {
        value.filter(present -> METADATA_VALUE.matcher(present).matches())
                .ifPresent(present -> metadata.put(name, present));
    }
