/**
 * @param fileName the path after /logs/, exactly as uploaded
 * @param headers the request headers
 * @param contentLength the request Content-Length, empty if it has none
 * @param body opened only once every check has passed
 */
public UploadOutcome upload(String fileName, HttpHeaders headers, OptionalLong contentLength, Body body) {
    Instant receivedAt = clock.instant();
    PolicyDecision decision = policy.check(fileName, headers, contentLength);
    if (decision instanceof PolicyDecision.Rejected rejected) {
        return new UploadOutcome.Rejected(rejected.reason(), rejected.file(), rejected.identity(), Optional.empty(),
                contentLength, Optional.empty(), since(receivedAt));
    }
    PolicyDecision.Allowed allowed = (PolicyDecision.Allowed) decision;
    LogFileName file = allowed.file();
    ClientIdentity identity = allowed.identity();
    ObjectKey key = new ObjectKey(file.mac(), receivedAt, file.type());
    LogObject object = new LogObject(key, allowed.contentLength(),
            Optional.ofNullable(headers.getFirst(HttpHeaders.USER_AGENT)), identity.sourceIp(),
            identity.certSerial(), file.manual(), file.name());

    TrackedBody tracked;
    try {
        tracked = new TrackedBody(body.open());
    } catch (IOException e) {
        return rejected(bodyRejection(e), allowed, key, Optional.of(e), receivedAt);
    }

